-- ============================================================================
-- Migration 838: chemical milling machine envelope and specs
-- ============================================================================
-- From memory/Machining/machine (etch_cell_usa, mask_cure_usa, scribe_usa,
-- demask_usa). Every location twin of each machine (matched by machine_class
-- and machine_name) gets the machine's own envelope in max_x/y/z_mm (etch tank,
-- cure oven, scribe bed) and its process specs merged into specs: heated_cure
-- (oven), feed_rate_mm_per_min, rapid_traverse_rate_mm_per_min and
-- programming_time_hr (scribe). The chemical-milling engine fits parts per tank
-- / oven load from the envelope and prices scribing from the feed rate.
-- One statement, idempotent. Needs migrations 738 and 814a.
-- Generated by scripts/gen_838_chemical_milling_machine_specs.js.
-- ============================================================================

UPDATE mhr_records m
SET max_x_mm = coalesce(v.max_x, m.max_x_mm),
    max_y_mm = coalesce(v.max_y, m.max_y_mm),
    max_z_mm = coalesce(v.max_z, m.max_z_mm),
    specs    = coalesce(m.specs, '{}'::jsonb) || v.spec
FROM (VALUES
  ($str$etch_cell$str$, $str$Etch Cell - 1.8m x 1.0m x 1.2m Tank Size$str$, 1800::numeric, 1050::numeric, 1200::numeric, $jsonb${}$jsonb$::jsonb),
  ($str$etch_cell$str$, $str$Etch Cell - 12.2m x 2.1m x 3.0m Tank Size$str$, 12192::numeric, 2133::numeric, 3048::numeric, $jsonb${}$jsonb$::jsonb),
  ($str$etch_cell$str$, $str$Etch Cell - 3.6m x 2.1m x 2.4m Tank Size$str$, 3600::numeric, 2100::numeric, 2400::numeric, $jsonb${}$jsonb$::jsonb),
  ($str$etch_cell$str$, $str$Etch Cell - 7.2m x 4.2m x 4.8m Tank Size$str$, 7200::numeric, 4200::numeric, 4800::numeric, $jsonb${}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Curing Oven - 1.3m x 1.3m x 1.4m Useable Oven Size$str$, 1317::numeric, 1367::numeric, 1467::numeric, $jsonb${"heated_cure":true}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Drying Room - 1.3m x 1.3m x 1.4m Useable Drying Room Size$str$, 1317::numeric, 1367::numeric, 1467::numeric, $jsonb${"heated_cure":false}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Curing Oven - 12.1m x 2.1m x 4.0m Useable Oven Size$str$, 12192::numeric, 2133::numeric, 4000::numeric, $jsonb${"heated_cure":true}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Drying Room - 12.1m x 2.1m x 4.0m Useable Drying Room Size$str$, 12192::numeric, 2133::numeric, 4000::numeric, $jsonb${"heated_cure":false}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Curing Oven - 2.9m x 2.5m x 2.0m Useable Oven Size$str$, 2917::numeric, 2500::numeric, 2000::numeric, $jsonb${"heated_cure":true}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Drying Room - 2.9m x 2.5m x 2.0m Useable Drying Room Size$str$, 2917::numeric, 2500::numeric, 2000::numeric, $jsonb${"heated_cure":false}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Curing Oven - 5.5m x 4.1m x 3.0m Useable Oven Size$str$, 5500::numeric, 4167::numeric, 3000::numeric, $jsonb${"heated_cure":true}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Drying Room - 5.5m x 4.1m x 3.0m Useable Drying Room Size$str$, 5500::numeric, 4167::numeric, 3000::numeric, $jsonb${"heated_cure":false}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Curing Oven Overhead Conveyor - 5.9m x 3.3m x 2.8m Useable Oven Size$str$, 5917::numeric, 3361::numeric, 2800::numeric, $jsonb${"heated_cure":true}$jsonb$::jsonb),
  ($str$mask_cure$str$, $str$Drying Room Overhead Conveyor - 5.9m x 3.3m x 2.8m Useable Drying Room Size$str$, 5917::numeric, 3361::numeric, 2800::numeric, $jsonb${"heated_cure":false}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Laser Scribe - 0.35m x 0.35m x 0.35m Bed Size$str$, 355::numeric, 355::numeric, 355::numeric, $jsonb${"feed_rate_mm_per_min":7000,"rapid_traverse_rate_mm_per_min":15200,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Laserdyne Systems 450$str$, 355::numeric, 355::numeric, 355::numeric, $jsonb${"feed_rate_mm_per_min":7000,"rapid_traverse_rate_mm_per_min":15200,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Laser Scribe - 1.5m x 1m x 1m Bed Size$str$, 1500::numeric, 1000::numeric, 1000::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Gantry Laser Scribe - 15m x 4m x 1.5m Bed Size$str$, 15000::numeric, 4000::numeric, 1500::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$mTorres TorresLaser$str$, 15000::numeric, 4000::numeric, 1500::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Laserdyne Systems 795XS$str$, 1000::numeric, 1000::numeric, 1000::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Gantry Laser Scribe - 2.4m x 1.8m x 0.9m Bed Size$str$, 2400::numeric, 1800::numeric, 900::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Laserdyne Systems 890$str$, 2400::numeric, 1800::numeric, 900::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$scribe$str$, $str$Laserdyne Systems 795XL$str$, 2000::numeric, 1000::numeric, 1000::numeric, $jsonb${"feed_rate_mm_per_min":10000,"rapid_traverse_rate_mm_per_min":20000,"programming_time_hr":1}$jsonb$::jsonb),
  ($str$demask$str$, $str$DeMask Cell - 10m x 10m Footprint$str$, NULL::numeric, NULL::numeric, NULL::numeric, $jsonb${}$jsonb$::jsonb),
  ($str$demask$str$, $str$DeMask Cell - 12m x 10m Footprint$str$, NULL::numeric, NULL::numeric, NULL::numeric, $jsonb${}$jsonb$::jsonb)
) AS v(machine_class, machine_name, max_x, max_y, max_z, spec)
WHERE m.machine_class = v.machine_class AND m.machine_name = v.machine_name;

NOTIFY pgrst, 'reload schema';

